fn count_matches<T: PartialEq>(list: &[T], target: &T) -> usize {
    let mut count = 0;
    for item in list {
        if item == target {
            count += 1;
        }
    }
    count
}

fn main() {
    let words = vec![String::from("hi"), String::from("yo"), String::from("hi")];
    println!("{}", count_matches(&words, &String::from("hi")));

    let tickets = vec![Ticket { seat: 4 }, Ticket { seat: 9 }];
    let wanted = Ticket { seat: 9 };
    println!("seat {}: {}", wanted.seat, count_matches(&tickets, &wanted));
}

fn count_above<T: ___>(list: &[T], limit: &T) -> usize {
    let mut count = 0;
    for item in list {
        if item > limit {
            count += 1;
        }
    }
    count
}

