struct SocialPost {
    username: String,
}

impl Summary for SocialPost {
    fn summarize(&self) -> String {
        format!("@{}", self.username)
    }
}

fn notify<T: Summary>(item: &T) {
    println!("Breaking news! {}", item.summarize());
}

fn notify_both(item1: &impl Summary, item2: &impl Summary) {
    println!("{} | {}", item1.summarize(), item2.summarize());
}

fn notify_same<T: Summary>(item1: &T, item2: &T) {
    println!("{} | {}", item1.summarize(), item2.summarize());
}

fn main() {
    let article = NewsArticle {
        headline: String::from("Penguins win!"),
    };
    let post = SocialPost {
        username: String::from("horse_ebooks"),
    };
    let other_post = SocialPost {
        username: String::from("ferris"),
    };

    notify(&article);
    notify_both(&article, &post);
    notify_same(&post, &other_post);
}

