fn mark_above<T>(items: &[T], limit: &T) -> String
where
    T: PartialOrd + Display,
{
    let mut text = String::new();
    for item in items {
        if item > limit {
            text.push_str(&format!("[{item}]"));
        } else {
            text.push_str(&format!("{item}"));
        }
    }
    text
}

